import { fileURLToPath } from "node:url";
export default defineConfig({
  root: fileURLToPath(new URL("../..", import.meta.url)),
  test: { environment: "node", include: ["probe/verify-card-judge/**/*.probe.ts"],
    setupFiles: ["tests/setup.ts"], chaiConfig: { truncateThreshold: 200 } },
});
MORPH_CONF_EOF
cat > $P/tsconfig.card.json <<'MORPH_TSCONF_EOF'
{
  "extends": "../../tsconfig.json",
  "include": [
    "../../src",
    "../../tests",
    "./*.probe.ts"
  ]
}
MORPH_TSCONF_EOF
echo '== tsc'; node_modules/.bin/tsc --noEmit -p $P/tsconfig.card.json
echo '== eslint'; node_modules/.bin/eslint tests/acceptance/verify.examples.test.ts
cat > $P/lits.json <<'MORPH_LITS_EOF'
["c.v3", "answer corrupt: missing section for src/a.ts", "answer truncated", "@@ -1,1 +1,1 @@"]
MORPH_LITS_EOF
echo '== guard'; node $P/guard.mjs tests tests/acceptance/verify.examples.test.ts 3 15 $P/lits.json
echo '== own'; node_modules/.bin/vitest run tests/acceptance/verify.examples.test.ts --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== full'; node_modules/.bin/vitest run --passWithNoTests --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e tests/acceptance/verify.examples.test.ts || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc
